#nullable enable
namespace CardGame.Core.NativeOwners;
internal sealed class SelectionSourceQueries(EngineStates.CoreMatchParticipantsState matchParticipantsState, Func<RuntimeEntries.CoreGameEngineHealthQueriesEntries> getCoreGameEngineHealthQueriesRuntime, Func<RuntimeEntries.CorePhysicalOwnedCardQueriesEntries> getCorePhysicalOwnedCardQueriesRuntime, Func<RuntimeEntries.CoreGameEngineTreatedWoundedEntries> getCoreGameEngineTreatedWoundedRuntime, Func<CardZoneStore> getCardZoneStore, Func<RuntimeEntries.CoreGameEngineCardUseModulesEntries> getCoreGameEngineCardUseModulesRuntime, Func<RuntimeEntries.CoreGameEngineCardConversionsEntries> getCoreGameEngineCardConversionsRuntime, Func<RuntimeEntries.CoreProgramParticipantPhaseOperationsEntries> getCoreProgramParticipantPhaseOperationsRuntime, Func<RuntimeEntries.CoreNativeCardAppearanceEntries> getCoreNativeCardAppearanceRuntime, Func<RuntimeEntries.CoreGameEngineWenhePoisonEntries> getCoreGameEngineWenhePoisonRuntime, Func<RuntimeEntries.CoreGameEngineHpLossSlashMaterialsEntries> getCoreGameEngineHpLossSlashMaterialsRuntime, Func<RuntimeEntries.CoreNativeTargetLegalityEntries> getCoreNativeTargetLegalityRuntime, Func<RuntimeEntries.CoreGameEngineAlternatingSuitAndCompletedTopEntries> getCoreGameEngineAlternatingSuitAndCompletedTopRuntime, Func<RuntimeEntries.CoreGameEngineTurnRedSlashBenefitsEntries> getCoreGameEngineTurnRedSlashBenefitsRuntime, Func<RuntimeEntries.CoreGameEngineDirectedCardPolicyQueriesEntries> getCoreGameEngineDirectedCardPolicyQueriesRuntime, Func<RuntimeEntries.CoreGameEngineProgramOrdinaryTrickUsesEntries> getCoreGameEngineProgramOrdinaryTrickUsesRuntime, Func<RuntimeEntries.CoreNativeEquipmentAndFactionQueriesEntries> getCoreNativeEquipmentAndFactionQueriesRuntime, Func<RuntimeEntries.CoreGameEngineNextActualUseTargetAdjustmentsEntries> getCoreGameEngineNextActualUseTargetAdjustmentsRuntime, Func<RuntimeEntries.CoreNativeDamagePoliciesEntries> getCoreNativeDamagePoliciesRuntime, Func<RuntimeEntries.CoreGameEngineDeckEquipmentProgramsEntries> getCoreGameEngineDeckEquipmentProgramsRuntime) : IProgramSelectionSourceQuery
{
    public IReadOnlyList<ProgramSelectionParticipant> Participants() => Array.AsReadOnly(matchParticipantsState.ReferenceToPlayers.Select(player => new ProgramSelectionParticipant(player.Seat, player.IsAlive, getCoreGameEngineHealthQueriesRuntime().UnambiguousHp(player), player.MaxHp, player.HasHpValue, getCorePhysicalOwnedCardQueriesRuntime().GetHand(player).Count, getCorePhysicalOwnedCardQueriesRuntime().GetEquipment(player).Count, player.HappyQiaoHealth is not null || getCoreGameEngineTreatedWoundedRuntime().UsesTreatedWounded ? getCoreGameEngineTreatedWoundedRuntime().IsRuleWounded(player) : null)).ToArray());
    public IReadOnlyList<Card> Hand(int seat) => Array.AsReadOnly(getCorePhysicalOwnedCardQueriesRuntime().GetHand(matchParticipantsState.ReferenceToPlayers[seat]).Select(ProgramSelectionProjection.Freeze).ToArray());
    public IReadOnlyList<Card> Equipment(int seat) => Array.AsReadOnly(getCorePhysicalOwnedCardQueriesRuntime().GetEquipment(matchParticipantsState.ReferenceToPlayers[seat]).Select(ProgramSelectionProjection.Freeze).ToArray());
    public CardLocation Location(int cardId) => getCardZoneStore().GetLocation(cardId);
    public bool IsHandRestricted(int seat, Card card) => getCoreGameEngineCardUseModulesRuntime().IsTurnHandCardRestricted(matchParticipantsState.ReferenceToPlayers[seat], card);
    public bool HasCardIdentity(int seat, Card card) => getCoreGameEngineCardConversionsRuntime().HasProgramCardIdentity(matchParticipantsState.ReferenceToPlayers[seat], card);
    public bool IsUseForbidden(int seat, CardKind kind) => getCoreGameEngineCardUseModulesRuntime().IsCardUseForbidden(seat, kind, CardActionType.Use);
    public bool IsPhysicalUseForbidden(int seat, int cardId) => getCoreProgramParticipantPhaseOperationsRuntime().IsTurnPhysicalUseForbidden(seat, [cardId]);
    public Suit EffectiveSuit(int seat, Card card) => getCoreNativeCardAppearanceRuntime().EffectiveSuit(matchParticipantsState.ReferenceToPlayers[seat], card);
    public CardKind EffectiveInputKind(int seat, Card card) => getCoreGameEngineWenhePoisonRuntime().EffectiveConversionInputKind(matchParticipantsState.ReferenceToPlayers[seat], card);
    public IReadOnlyList<ProgramMultiCardViewAsSelection> Conversions(int seat, CardKind kind) => Array.AsReadOnly(getCoreGameEngineCardConversionsRuntime().GetProgramMultiCardViewAsSelections(matchParticipantsState.ReferenceToPlayers[seat], kind, false).Select(selection => ProgramSelectionProjection.Freeze(selection)!).ToArray());
    public bool HasHpLossTargets(int seat) => getCoreGameEngineHpLossSlashMaterialsRuntime().HasHpLossSlashTargets(matchParticipantsState.ReferenceToPlayers[seat]);
    public bool CanUseSlash(int owner, int target, IReadOnlyList<Card>? cards, bool ignoreDistance) => cards is null ? getCoreNativeTargetLegalityRuntime().CanUseVirtualSlashTarget(matchParticipantsState.ReferenceToPlayers[owner], matchParticipantsState.ReferenceToPlayers[target], ignoreDistance: ignoreDistance) : getCoreNativeTargetLegalityRuntime().CanUseVirtualSlashTarget(matchParticipantsState.ReferenceToPlayers[owner], matchParticipantsState.ReferenceToPlayers[target], physicalSuit: getCoreGameEngineAlternatingSuitAndCompletedTopRuntime().PhysicalGroupSuit(matchParticipantsState.ReferenceToPlayers[owner], cards), effectiveColor: getCoreGameEngineTurnRedSlashBenefitsRuntime().PhysicalGroupColor(matchParticipantsState.ReferenceToPlayers[owner], cards), physicalCardIds: cards.Select(card => card.Id).ToArray());
    public bool CanUseGlobal(int owner, CardKind kind) => getCoreGameEngineDirectedCardPolicyQueriesRuntime().CanUseGlobalCard(matchParticipantsState.ReferenceToPlayers[owner], kind);
    public bool CanUseOrdinaryTrick(int owner, CardKind? kind, IReadOnlyList<int> physicalCards) => getCoreGameEngineProgramOrdinaryTrickUsesRuntime().BuildProgramOrdinaryTrickUseOptions(matchParticipantsState.ReferenceToPlayers[owner], kind, enforceUsePermission: true, physicalCardIds: physicalCards, includeNextActualUseAdjustment: true).Count != 0;
    public bool CanRequestFactionSlash(int owner, string faction) => getCoreNativeEquipmentAndFactionQueriesRuntime().CanUseFactionSlashRequest(matchParticipantsState.ReferenceToPlayers[owner], faction);
    public bool HasNextUseAdjustment(int owner) => getCoreGameEngineNextActualUseTargetAdjustmentsRuntime().CurrentNextActualUseAdjustment(owner)is not null;
    public bool IsTargetProhibited(int target, CardKind kind, int owner, IReadOnlyList<Card> cards) => getCoreNativeDamagePoliciesRuntime().IsCardTargetProhibited(matchParticipantsState.ReferenceToPlayers[target], kind, getCoreGameEngineAlternatingSuitAndCompletedTopRuntime().PhysicalGroupSuit(matchParticipantsState.ReferenceToPlayers[owner], cards), getCoreGameEngineTurnRedSlashBenefitsRuntime().PhysicalGroupColor(matchParticipantsState.ReferenceToPlayers[owner], cards));
    public bool HasSuitShield(int owner, int target, IReadOnlyList<Card> cards) => getCoreGameEngineDeckEquipmentProgramsRuntime().HasBeneficiarySuitShield(owner, target, getCoreGameEngineAlternatingSuitAndCompletedTopRuntime().PhysicalGroupSuit(matchParticipantsState.ReferenceToPlayers[owner], cards));
    public int HpLossMaximum(int owner, CardKind kind) => getCoreGameEngineHpLossSlashMaterialsRuntime().HpLossSlashMaximum(matchParticipantsState.ReferenceToPlayers[owner], kind);
}
